files = tools.list_files("incident_cascade/*")
per_file = []
trc_9041_files = []
trc_9042_files = []
critical_files = []
total_errors = 0
total_warns = 0
slow_retry_noise = 0
cache_miss_noise = 0
for path in files:
    content = tools.read_file(path)
    errs = 0
    warns = 0
    c_9041 = 0
    c_9042 = 0
    crit = 0
    for line in content.splitlines():
        if "ERROR" in line:
            errs += 1
        if "WARN" in line:
            warns += 1
        if "trace_id=trc-9041" in line:
            c_9041 += 1
        if "trace_id=trc-9042" in line:
            c_9042 += 1
        if "CRITICAL_POOL_EXHAUSTED" in line:
            crit += 1
        if "upstream_slow_retry" in line:
            slow_retry_noise += 1
        if "cache_miss_fallback" in line:
            cache_miss_noise += 1
    total_errors += errs
    total_warns += warns
    if c_9041 > 0:
        trc_9041_files.append({"file": path, "matches": c_9041})
    if c_9042 > 0:
        trc_9042_files.append({"file": path, "matches": c_9042})
    if crit > 0:
        critical_files.append({"file": path, "code": "CRITICAL_POOL_EXHAUSTED", "count": crit})
    per_file.append({"file": path, "errors": errs, "warnings": warns})
result = {
    "files_analyzed": len(files),
    "total_errors": total_errors,
    "total_warnings": total_warns,
    "deduplicated_noise": {
        "upstream_slow_retry": slow_retry_noise,
        "cache_miss_fallback": cache_miss_noise
    },
    "critical_findings": critical_files,
    "correlated_traces": {
        "trc-9041": trc_9041_files,
        "trc-9042": trc_9042_files
    },
    "by_file": per_file
}

content = tools.read_file("data/logs/incident_cascade/malformed-collector.txt")
lines = content.splitlines()
empty_lines = 0
valid_info = 0
valid_warn = 0
valid_error = 0
malformed_lines = 0
backpressure_errors = 0
for raw_line in lines:
    trimmed = raw_line.strip()
    if len(trimmed) == 0:
        empty_lines += 1
    elif trimmed.startswith("2026-10-25T") and (" INFO " in trimmed or " WARN " in trimmed or " ERROR " in trimmed):
        if " INFO " in trimmed:
            valid_info += 1
        elif " WARN " in trimmed:
            valid_warn += 1
        else:
            valid_error += 1
            if "BACKPRESSURE" in trimmed:
                backpressure_errors += 1
    else:
        malformed_lines += 1
result = {
    "file": "data/logs/incident_cascade/malformed-collector.txt",
    "total_lines": len(lines),
    "empty_lines": empty_lines,
    "valid_info": valid_info,
    "valid_warn": valid_warn,
    "valid_error": valid_error,
    "malformed_lines": malformed_lines,
    "backpressure_errors": backpressure_errors
}

